        yield this as GraphPointer<typeof rule>;
      } else {
        yield* this.parent.resolve(true);
      }
    } else if (isRuleChar(rule) || isRuleCharExclude(rule)) {
      yield this as GraphPointer<typeof rule>;
    } else {
      throw new Error(`Unknown rule: ${JSON.stringify(rule)}`);
    }
  }

