    if (typeof text !== 'string') {
      throw new Error('input text must be of type string');
    }
    return new ParseState(this.#graph, this.#graph.add(text, this.#pointers));
  }

  get size(): number {
    return [...this.rules()].length;
  }

  get grammar(): string {
    return this.#graph.grammar;
